urlset:
{{ range .Data.Pages }}
{{ if not (or .Params.private .Params.block_external_search_index) }}

  {{ .Site.Params.canonicalURL }}{{ .RelPermalink }}
  {{ if not .Lastmod.IsZero -}}
  {{ safeHTML ( .Lastmod.Format "2006-01-02T15:04:05-07:00" ) }}
  {{- else -}}
  {{ now.Format "2006-01-02T15:04:05-07:00" | safeHTML }}
  {{- end }}
  {{- with .Sitemap.ChangeFreq -}}
  {{ . }}
  {{- else -}}
  {{ if eq .Section "blog" }}weekly{{ else }}monthly{{ end }}
  {{- end }}
  {{- if ge .Sitemap.Priority 0.0 -}}
  {{ .Sitemap.Priority }}
  {{- else -}}
  {{ if eq .RelPermalink "/" }}1.0{{ else if eq .Section "docs" }}0.9{{ else if eq .Section "blog" }}0.8{{ else if eq .Section "tutorials" }}0.8{{ else }}0.7{{ end }}
  {{- end }}
  {{ if .IsTranslated -}}
  {{ range .Translations }}

  {{ end }}

  {{- end }}

{{ end }}
{{ end }}
